    int base = atoi(argv[2]);

    char* converted_number = (char*)malloc(32 * sizeof(char));
    int remainder, index = 0;

    while (number > 0) {
        remainder = number % base;
        number /= base;

        if (remainder >= 10) {
            converted_number[index++] = 'A' + (remainder - 10);
        } else {
